/**
 * 锁档类型（字面联合）：与 contracts 的 `LockTier`
 * （packages/contracts/src/chest）取值保持一致（iron/copper/silver/gold）。
 * 规则层以本类型为权威，显式字面联合可在编译期约束越界 tier。
 */
export type LockTier = 'iron' | 'copper' | 'silver' | 'gold';

/** 已定（v5.5 8.4）：连续命中 n 次才开锁，失误归零，每次蓄力消耗一根工具。 */
export const LOCK_HITS: Readonly<Record<LockTier, number>> = { iron: 1, copper: 2, silver: 3, gold: 4 };

/**
 * 连续命中 n 次所需的期望尝试次数（= 期望消耗工具数）。p 为单次命中率（0..1，需真机实测）。
 * E = (1 - p^n) / ((1 - p) * p^n)
 */
export function expectedAttempts(p: number, n: number): number {
  if (p >= 1) return n;
  if (p <= 0) return Infinity;
  const pn = Math.pow(p, n);
  return (1 - pn) / ((1 - p) * pn);
}

/** 单次判定：指针位置是否落在命中区（均为 0..10000 的万分比刻度）。 */
export function isHit(pointer: number, zoneStart: number, zoneWidth: number): boolean {
  return pointer >= zoneStart && pointer < zoneStart + zoneWidth;
}

/** 一局开锁会话状态（不可变：每次 attempt 返回新对象）。 */
export interface LockSession {
  tier: LockTier;
  /** 当前连续命中数（失误归零），用于判定是否开锁 */
  consecutiveHits: number;
  /** 累计命中数（失误不重置）—— 即"已中数" */
  totalHits: number;
  /** 剩余工具数（用一次断一根） */
  toolsLeft: number;
  /** 是否已开锁（一旦达成不回退） */
  unlocked: boolean;
}

/** 开局：给定锁档与初始工具数。 */
export function createSession(tier: LockTier, tools: number): LockSession {
  return { tier, consecutiveHits: 0, totalHits: 0, toolsLeft: Math.max(0, tools), unlocked: false };
}

/**
 * 一次尝试（确定性、纯函数）：
 * - 命中 → consecutiveHits+1、totalHits+1；失误 → consecutiveHits 归零、totalHits 不减。
 * - 无论命中与否，toolsLeft 消耗 1（用一次断一根）。
 * - consecutiveHits 达到该档所需次数 → unlocked=true（不回退）。
 * - toolsLeft 降至 0 → terminated=true（本局终止）。
 */
export function attempt(
  session: LockSession,
  hit: boolean,
): { session: LockSession; hit: boolean; terminated: boolean } {
  // 已终止（无工具）的会话不再推进，避免 toolsLeft 变负、语义歧义
  if (session.toolsLeft <= 0) return { session, hit, terminated: true };
  const required = LOCK_HITS[session.tier];
  const consecutiveHits = hit ? session.consecutiveHits + 1 : 0;
  const totalHits = session.totalHits + (hit ? 1 : 0);
  const toolsLeft = session.toolsLeft - 1;
  const unlocked = session.unlocked || consecutiveHits >= required;
  const terminated = toolsLeft <= 0;
  return {
    session: { tier: session.tier, consecutiveHits, totalHits, toolsLeft, unlocked },
    hit,
    terminated,
  };
}
